import json,os,subprocess,collections
from dotenv import dotenv_values
cli='/Users/tanishqpalandurkar/.local/bin/slack';channel='D0C6F49F2KD'
env={k:v for k,v in os.environ.items() if not k.startswith('SLACK_')};env['SLACK_BOT_TOKEN']=dotenv_values('.local/hermes-lab/home/.env',interpolate=False)['SLACK_BOT_TOKEN']
def call(method,**params):
    args=[cli,'api',method]+[k+'='+str(v) for k,v in params.items()]+['--skip-update','--no-color']
    r=subprocess.run(args,env=env,capture_output=True,text=True,timeout=45)
    try:value=json.loads(r.stdout)
    except Exception:raise RuntimeError('Slack CLI response was not JSON')
    if not value.get('ok'):raise RuntimeError(json.dumps({k:value[k] for k in ('error','needed','provided') if k in value}))
    return value
info=call('conversations.info',channel=channel)['channel']
print('conversation',json.dumps({k:info.get(k) for k in ('id','user','is_im','is_open')}),flush=True)
messages={};roots=[];cursor='';pages=0
while True:
    value=call('conversations.history',channel=channel,limit=200,**({'cursor':cursor} if cursor else {}));pages+=1
    for m in value.get('messages',[]):
        messages[m['ts']]=m
        if m.get('reply_count',0):roots.append(m['ts'])
    cursor=value.get('response_metadata',{}).get('next_cursor','')
    if not cursor:break
print('history',json.dumps({'root_messages':len(messages),'pages':pages,'thread_count':len(set(roots))}),flush=True)
for ts in sorted(set(roots)):
    cursor=''
    while True:
        value=call('conversations.replies',channel=channel,ts=ts,limit=200,**({'cursor':cursor} if cursor else {}))
        for m in value.get('messages',[]):messages[m['ts']]=m
        cursor=value.get('response_metadata',{}).get('next_cursor','')
        if not cursor:break
counts=collections.Counter(m.get('user') or ('bot:'+m.get('bot_id','unknown')) for m in messages.values())
print('message_totals',json.dumps({'all_messages_including_replies':len(messages),'by_sender':dict(counts),'thread_roots':len(set(roots))}),flush=True)
PY","max_output_tokens":2500,"yield_time_ms":10000}));

