import argparse
import collections
import concurrent.futures
import json
import os
from pathlib import Path
import re
import subprocess
import threading
import time

from dotenv import dotenv_values

ROOT = Path('/Users/tanishqpalandurkar/Projects/yyot')
CLI = '/Users/tanishqpalandurkar/.local/bin/slack'
CHANNEL = 'D0C6F49F2KD'
TEAM = 'T0C6J1XCDE0'
HUMAN = 'U0C6M6DMWAW'
BOT = 'U0C5Z1ZQHQX'
PLAN = Path('/tmp/clanker-dm-cleanup-plan.json')
STATE = Path('/tmp/clanker-dm-cleanup-state.json')
TOKEN = Path('/tmp/clanker-dm-cleanup-user-token')
BOT_TOKEN = dotenv_values(ROOT / '.local/hermes-lab/home/.env', interpolate=False)['SLACK_BOT_TOKEN']
THROTTLE = threading.Lock()
NEXT_CALL = 0.0


def private_json(path, value):
    fd = os.open(path, os.O_CREAT | os.O_TRUNC | os.O_WRONLY, 0o600)
    with os.fdopen(fd, 'w') as stream:
        json.dump(value, stream)


def call(token, method, **params):
    global NEXT_CALL
    for attempt in range(4):
        with THROTTLE:
            pause = max(0, NEXT_CALL - time.monotonic())
            if pause:
                time.sleep(pause)
            NEXT_CALL = time.monotonic() + 1.3
        env = {key: value for key, value in os.environ.items() if not key.startswith('SLACK_')}
        env['SLACK_USER_TOKEN'] = token
        args = [CLI, 'api', method] + [f'{key}={value}' for key, value in params.items()]
        args += ['--include', '--skip-update', '--no-color']
        result = subprocess.run(args, env=env, text=True, capture_output=True, timeout=45)
        start = result.stdout.find('{')
        if start < 0:
            raise RuntimeError(f'{method}: unparseable CLI response; outcome unknown')
        try:
            value = json.loads(result.stdout[start:])
        except ValueError:
            raise RuntimeError(f'{method}: unparseable CLI response; outcome unknown') from None
        if value.get('error') in ('ratelimited', 'rate_limited') and attempt < 3:
            retry = re.search(r'(?im)^retry-after:\s*(\d+)', result.stdout[:start])
            delay = int(retry.group(1)) if retry else 30
            print(json.dumps({'status': 'rate_limited', 'method': method, 'retry_in_seconds': delay}), flush=True)
            time.sleep(min(delay, 60))
            continue
        if not value.get('ok'):
            raise RuntimeError(f'{method}: {value.get("error", "unknown_error")}')
        return value
    raise RuntimeError(f'{method}: rate limit retries exhausted')


def pages(method, **params):
    cursor = ''
    while True:
        value = call(BOT_TOKEN, method, limit=200, **params, **({'cursor': cursor} if cursor else {}))
        yield from value.get('messages', [])
        cursor = value.get('response_metadata', {}).get('next_cursor', '')
        if not cursor:
            break


def inspect():
    bot_identity = call(BOT_TOKEN, 'auth.test')
    if bot_identity.get('team_id') != TEAM or bot_identity.get('user_id') != BOT:
        raise RuntimeError('Unexpected bot identity')
    conversation = call(BOT_TOKEN, 'conversations.info', channel=CHANNEL)['channel']
    if not conversation.get('is_im') or conversation.get('user') != HUMAN:
        raise RuntimeError('Unexpected DM identity')
    messages = {message['ts']: message for message in pages('conversations.history', channel=CHANNEL)}
    roots = sorted(ts for ts, message in messages.items() if message.get('reply_count', 0))
    print(json.dumps({'status': 'reading_threads', 'history_messages': len(messages), 'threads': len(roots)}), flush=True)
    def read_thread(ts):
        return list(pages('conversations.replies', channel=CHANNEL, ts=ts))
    with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
        for index, replies in enumerate(pool.map(read_thread, roots), 1):
            for message in replies:
                messages[message['ts']] = message
            if index % 10 == 0:
                print(json.dumps({'status': 'reading_threads', 'completed_threads': index, 'threads': len(roots)}), flush=True)
    metadata = [
        {'ts': message['ts'], 'user': message.get('user'), 'thread_ts': message.get('thread_ts')}
        for message in messages.values()
    ]
    counts = dict(collections.Counter(message['user'] for message in metadata))
    return {'channel': CHANNEL, 'team': TEAM, 'human': HUMAN, 'bot': BOT, 'roots': roots, 'messages': metadata, 'counts': counts}


def prepare():
    plan = inspect()
    expected = {HUMAN: 114, BOT: 199}
    if plan['counts'] != expected or len(plan['messages']) != 313:
        raise RuntimeError(f'DM changed since approval: counts={plan["counts"]}')
    private_json(PLAN, plan)
    print(json.dumps({'status': 'plan_ready', 'messages': len(plan['messages']), 'counts': plan['counts']}), flush=True)


def apply():
    plan = json.loads(PLAN.read_text())
    if plan['channel'] != CHANNEL or plan['counts'] != {HUMAN: 114, BOT: 199}:
        raise RuntimeError('Unexpected deletion plan')
    user_token = TOKEN.read_text().strip()
    identity = call(user_token, 'auth.test')
    if identity.get('user_id') != HUMAN or identity.get('team_id') != TEAM:
        raise RuntimeError('User token is not yyovil in the expected workspace')
    bot_identity = call(BOT_TOKEN, 'auth.test')
    if bot_identity.get('user_id') != BOT or bot_identity.get('team_id') != TEAM:
        raise RuntimeError('Unexpected bot identity')
    state = json.loads(STATE.read_text()) if STATE.exists() else {'channel': CHANNEL, 'deleted': []}
    if state['channel'] != CHANNEL:
        raise RuntimeError('Unexpected deletion state')
    deleted = set(state['deleted'])
    ordered = sorted(plan['messages'], key=lambda message: (not (message.get('thread_ts') and message['thread_ts'] != message['ts']), message['ts']))
    for message in ordered:
        if message['ts'] in deleted:
            continue
        if message['user'] not in (HUMAN, BOT):
            raise RuntimeError('Unexpected sender in deletion plan')
        token = user_token if message['user'] == HUMAN else BOT_TOKEN
        call(token, 'chat.delete', channel=CHANNEL, ts=message['ts'])
        deleted.add(message['ts'])
        state['deleted'] = sorted(deleted)
        private_json(STATE, state)
        if len(deleted) % 10 == 0 or len(deleted) == len(ordered):
            print(json.dumps({'status': 'deleting', 'deleted': len(deleted), 'total': len(ordered)}), flush=True)
    print(json.dumps({'status': 'deletion_calls_succeeded', 'deleted': len(deleted)}), flush=True)


def verify():
    plan = json.loads(PLAN.read_text())
    remaining = list(pages('conversations.history', channel=CHANNEL))
    surviving_replies = []
    for index, ts in enumerate(plan['roots'], 1):
        try:
            surviving_replies.extend(pages('conversations.replies', channel=CHANNEL, ts=ts))
        except RuntimeError as error:
            if str(error) != 'conversations.replies: thread_not_found':
                raise
        if index % 10 == 0:
            print(json.dumps({'status': 'verifying_threads', 'checked': index, 'total': len(plan['roots'])}), flush=True)
    result = {'status': 'verified_empty' if not remaining and not surviving_replies else 'messages_remain', 'history_messages': len(remaining), 'thread_messages': len(surviving_replies)}
    private_json(Path('/tmp/clanker-dm-cleanup-verification.json'), result)
    print(json.dumps(result), flush=True)
    if remaining or surviving_replies:
        raise RuntimeError('DM verification found remaining messages')


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('action', choices=['prepare', 'apply', 'verify'])
    args = parser.parse_args()
    {'prepare': prepare, 'apply': apply, 'verify': verify}[args.action]()

